import React from 'react';
import { CStatus } from '@cloud-materials/common';

CStatus.config({
  statusMap: {
    Test: {
      status: 'error',
      text: '测试',
    },
  },
});
export default () => {
  const statusNames = ['Usable', 'Error', 'Warning', 'Running', 'Wait', 'Disable'];

  return (
    <div>
      <p>内置statusMap 7种</p>
      {statusNames.map(statusName => (
        <div key={statusName}>
          <CStatus statusName={statusName} />
        </div>
      ))}
      <p>使用Status.config</p>
      <div>
        <CStatus statusName="Test" />
      </div>
      <p>使用传入statusMap</p>
      <div>
        <CStatus
          statusName="Test"
          statusMap={{
            Test: {
              status: 'usable',
              text: '测试',
            },
          }}
        />
        <CStatus statusName="Usable" statusMap={{}} />
      </div>
    </div>
  );
};

import React from 'react';
import { CStatus, Typography } from '@cloud-materials/common';
import { IconClose } from '@arco-design/iconbox-react-ve-o-design';

const { Title } = Typography;

CStatus.config({
  // text: 'config',
  className: 'class-custom',
  // style: { padding: '3px' },
  // color: 'pink',
  // tagColor: 'pink',
  // highlightColor: 'pink',
  // borderColor: 'pink',
});
export default () => {
  const statusNames = ['Usable', 'Error', 'Warning', 'Running', 'Wait', 'Disable'];

  return (
    <div>
      <Title heading={6}>优先级最高：在组件传入自定义icon、color等信息</Title>
      <CStatus status="usable" text="正常" />
      <div>
        <p>传入icon</p>
        <CStatus status="usable" text="正常" icon={<IconClose />} />
        <p>传入color, color为文字颜色，不影响icon</p>
        <CStatus status="usable" text="正常" icon={<IconClose />} color="red" />
        <p>传入tagColor，自定义tag模式下的背景色</p>
        <CStatus status="usable" text="正常" type="tag" tagColor="green" color="white" />
        <p>传入highlightColor，自定义高亮模式下的背景色</p>
        <CStatus status="error" text="正常" type="highlight" highlightColor="#eaf0fd" />
        <p>传入borderColor，自定义边框的颜色</p>
        <CStatus status="error" text="正常" type="tag" borderColor="black" />
      </div>
      <Title heading={6}>优先级高于默认设置和statusMap，用Status.config做统一设置</Title>
      <p>
        className、style等，
        <span style={{ color: 'red', fontSize: '24px' }}>对于text、颜色的统一设置，不要轻易使用！！</span>
      </p>
      {statusNames.map(statusName => (
        <div key={statusName}>
          <CStatus statusName={statusName} />
        </div>
      ))}
    </div>
  );
};

