import React from 'react';
import { CStatus, Typography } from '@cloud-materials/common';
import type { Type } from '../interface';

const { Title } = Typography;
const typeList = ['heavy', 'tag', 'highlight', 'normal', 'border', 'dot'];

CStatus.config({
  waitColor: 'blue',
});

export default () => {
  return (
    <div>
      <Title heading={6}>
        在业务中，对于wait状态，不同业务有蓝色blue和灰色grey两种配色需求。默认配置为灰色，可通过全局配置设定配置为蓝色。
      </Title>
      <div style={{ height: '80px', marginBottom: '16px' }}>
        {typeList.map(type => (
          <div style={{ margin: '0px 10px 0 0', display: 'inline-block' }} key={type}>
            <div style={{ height: '30px', position: 'relative' }}>
              <p>type={type}</p>
            </div>
            <div style={{ position: 'absolute' }}>
              <div style={{ marginBottom: '5px', height: '24px' }}>
                <CStatus type={type as Type} status="wait" text="wait" />
              </div>
            </div>
          </div>
        ))}
      </div>
      <Title heading={6}>在全局配置之后，对于局部页面有不同配色需求，可以通过传入waitColor参数进行配置。</Title>
      <div style={{ height: '80px', marginBottom: '16px' }}>
        {typeList.map(type => (
          <div style={{ margin: '0px 10px 0 0', display: 'inline-block' }} key={type}>
            <div style={{ height: '30px', position: 'relative' }}>
              <p>type={type}</p>
            </div>
            <div style={{ position: 'absolute' }}>
              <div style={{ marginBottom: '5px', height: '24px' }}>
                <CStatus type={type as Type} status="wait" text="wait" waitColor="grey" />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};
